import sys

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    n = data[0]
    seq = data[1:1 + n]

    dp = [[0] * (n + 1) for _ in range(n + 1)]
    ans = 1 if n > 0 else 0

    for x in seq:
        for y in range(1, n + 1):
            if y == x:
                continue
            prev = dp[y][x]
            val = prev + 1 if prev > 0 else 1
            if val > dp[x][y]:
                dp[x][y] = val
                if val > ans:
                    ans = val

    print(ans)

